def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_my = my[-1]
    last_opp = op[-1]

    op_d = 0
    my_d = 0
    after_c = 0
    after_d = 0
    for i in range(n):
        if my[i] == 'D':
            my_d += 1
            if i + 1 < n:
                if op[i + 1] == 'C':
                    after_c += 1
                else:
                    after_d += 1
        if op[i] == 'D':
            op_d += 1

    d3 = sum(1 for x in op[-3:] if x == 'D')
    d5 = sum(1 for x in op[-5:] if x == 'D')
    d10 = sum(1 for x in op[-10:] if x == 'D')
    recent_dc = sum(1 for a, b in zip(my[-10:], op[-10:]) if a == 'D' and b == 'C')
    recent_dd = sum(1 for a, b in zip(my[-10:], op[-10:]) if a == 'D' and b == 'D')

    exploit = False
    if n >= 12:
        if after_c >= 2 and after_c > after_d and d5 <= 1 and d10 <= 3 and op_d * 3 <= n:
            exploit = True
        elif after_c >= 1 and after_d == 0 and d5 == 0 and d10 <= 1 and op_d <= 2:
            exploit = True
        elif recent_dc >= 3 and recent_dd * 3 <= recent_dc and d5 <= 1 and d10 <= 4 and op_d * 3 <= n:
            exploit = True
        elif op_d == 0 and my_d >= 2:
            exploit = True

    if exploit:
        if d5 <= 1:
            if last_opp == 'C':
                return 'D'
            if last_my == 'D':
                dd_run = 0
                for i in range(n - 1, -1, -1):
                    if my[i] == 'D' and op[i] == 'D':
                        dd_run += 1
                    else:
                        break
                if dd_run >= 2:
                    return 'D'
                return 'C'
            return 'C'
        return 'D'

    if n < 10:
        return 'D' if last_opp == 'D' else 'C'

    if last_opp == 'C' and n == 10 and op_d <= 2 and d5 == 0 and after_d == 0:
        return 'D'

    if last_opp == 'D':
        if op_d * 5 >= n * 2 or d5 >= 4 or d10 >= 6:
            return 'D'

        if d3 >= 2 or d5 >= 2:
            if last_my == 'D':
                dd_run = 0
                for i in range(n - 1, -1, -1):
                    if my[i] == 'D' and op[i] == 'D':
                        dd_run += 1
                    else:
                        break
                if dd_run >= 2 and op_d * 3 < n:
                    return 'C'
            return 'D'

        if n >= 2 and my[-2] == 'D' and op[-2] == 'C' and last_my == 'C':
            return 'C'

        if last_my == 'D':
            return 'D'

        if op_d <= 2 and rng.random() < 0.5:
            return 'C'
        return 'D'

    if op_d == 0 and my_d == 0 and n >= 30 and rng.random() < 0.02:
        return 'D'

    return 'C'
